"""Portable figures and a self-contained English research report."""

import base64
import html
import json
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt


def write_report(output, daily, diagnostics, metrics, metadata):
    output = Path(output)
    output.mkdir(parents=True, exist_ok=True)
    plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 10, "axes.spines.top": False, "axes.spines.right": False})
    fig, axes = plt.subplots(1, 2, figsize=(12, 4.5), constrained_layout=True)
    axes[0].plot(daily.date, daily.gross_equity, color="#237d74", label="Gross long/short")
    axes[0].plot(daily.date, daily.net_equity, color="#c37836", label="Net of entry + exit costs")
    axes[0].axhline(1, color="#999999", lw=0.7)
    axes[0].set(title="Synthetic test portfolio", ylabel="Growth of 1 unit")
    axes[0].legend(frameon=False, fontsize=8)
    axes[0].tick_params(axis="x", rotation=25)
    ordered = diagnostics.sort_values("mean_rank_ic")
    axes[1].barh(ordered.feature, ordered.mean_rank_ic, color="#237d74")
    axes[1].axvline(0, color="#999999", lw=0.7)
    axes[1].set(title="Test-period factor diagnostics", xlabel="Mean daily rank IC")
    fig.suptitle("EQUITY FACTOR RESEARCH LAB | SYNTHETIC DATA ONLY", fontsize=12, fontweight="bold")
    figure = output / "overview.png"
    fig.savefig(figure, dpi=170, facecolor="#faf9f6")
    plt.close(fig)
    payload = {"data_type": "synthetic", "metrics": metrics, "experiment": metadata}
    (output / "summary.json").write_text(json.dumps(payload, indent=2, allow_nan=False) + "\n")
    image = base64.b64encode(figure.read_bytes()).decode()
    rows = "".join(f"<tr><td>{html.escape(k.replace('_', ' ').title())}</td><td>{v:.6f}</td></tr>" if isinstance(v, float) else f"<tr><td>{html.escape(k)}</td><td>{html.escape(str(v))}</td></tr>" for k, v in metrics.items())
    report = f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equity Factor Research Lab | Synthetic Demo</title>
<style>body{{max-width:1100px;margin:48px auto;padding:0 24px;background:#faf9f6;color:#202b34;font:16px/1.65 system-ui}}h1{{font-size:42px;line-height:1.12;max-width:800px}}.eyebrow{{letter-spacing:3px;color:#237d74;font-size:12px;font-weight:700}}.notice{{border-left:4px solid #c37836;padding:12px 20px;background:#fff}}img{{width:100%;margin:24px 0}}table{{width:100%;border-collapse:collapse}}td{{padding:9px;border-bottom:1px solid #ddd}}td:last-child{{text-align:right;font-variant-numeric:tabular-nums}}h2{{margin-top:36px}}code{{font-size:14px}}footer{{margin-top:40px;border-top:1px solid #ddd;padding-top:16px;font-size:13px}}</style>
<p class="eyebrow">RESEARCH / ENGINEERING / REPRODUCIBILITY</p><h1>Equity Factor<br>Research Lab</h1>
<p>A standalone demonstration of factor construction, cross-sectional processing, chronological model selection and cost-aware portfolio evaluation.</p>
<div class="notice"><strong>Synthetic demonstration only.</strong> These results were generated by the included simulator. They do not represent the original research archive, real securities, employer results or evidence of investable alpha.</div>
<img alt="Synthetic portfolio equity curves and daily factor rank IC" src="data:image/png;base64,{image}">
<h2>Experiment</h2><p>Seed {metadata['seed']}; {metadata['days']} business dates; {metadata['symbols']} fictional securities; eight features; twelve sampled intraday observations per security per day. Business dates are not an exchange holiday calendar.</p>
<p>Signal: after close t. Execution: open to close t+1. Dates split approximately 60% / 20% / 20%; labels crossing a partition boundary are purged. Ridge alpha is chosen on validation rank IC. The scaler and selected model retain their training-only fit.</p>
<h2>Untouched test-period results</h2><table>{rows}</table>
<p>Long the highest-scoring 20% and short the lowest-scoring 20%, with +0.5 / -0.5 portfolio weights. Positions close to cash every day. One-way cost is {metadata['cost_bps']} bps; gross exposure 1.0 implies round-trip turnover 2.0. Sharpe uses 252 sessions and zero risk-free rate.</p>
<h2>What a reviewer can verify</h2><p>CSV files contain raw factor exposures, processed exposures, test predictions, model coefficients, validation scores, daily portfolio returns and positions. The JSON summary records input settings, package versions, date partitions and selected alpha.</p>
<h2>Research limits</h2><p>Latent return structure is deliberately built into the simulator. The short holdout cannot establish statistical significance. Cross-sectional residualization precedes rank transformation, so final ranked features need not remain exactly industry or size neutral. The portfolio is a research abstraction: no borrow availability, financing, exchange price limits, execution delay, queueing or capacity model is included. A-share T+1 rules and short-sale constraints can make this intraday long/short portfolio infeasible.</p>
<footer>Prepared for technical portfolio review. See the repository methodology and provenance notes before interpreting any result.</footer></html>'''
    (output / "demo_report.html").write_text(report, encoding="utf-8")
